// spec: .qa/e2e/specs/history.md (2.1)
// seed: tests/seed.user.spec.ts
import { test, expect, type Route } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

// Запрос списка «היסטוריה» (выборка со status — у «ניטורים אחרונים» на בית её нет).
const isHistoryList = (u: URL) => u.pathname.endsWith('/rest/v1/monitoring_sessions') && /^id,status,/.test(u.searchParams.get('select') ?? '');

test.describe('История — загрузка и догрузка', () => {
  test('История: при медленной загрузке — индикатор, не пусто и не ошибка; «ניטורים קודמים» догружает следующие записи #78e3149c @iphone @prod-safe', async ({ page }) => {
    // 1. Удерживаем ответ списка до сигнала (медленная сеть без фиксированной паузы; только веб — перехват запроса)
    let release!: () => void;
    let held = new Promise<void>((r) => (release = r));
    let calls = 0;
    await page.route(isHistoryList, async (route: Route) => {
      calls++;
      await held;
      await route.continue();
    });

    // 2. Открыть /history
    await page.goto('/history');
    await expect.poll(() => calls).toBeGreaterThan(0);

    // 3. Пока ответ удержан — индикатор загрузки, нет пустого состояния и ошибки
    await expect(page.getByRole('progressbar').filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText('עוד אין ניטורים').filter({ visible: true })).toHaveCount(0);
    await expect(page.getByText(/משהו השתבש/).filter({ visible: true })).toHaveCount(0);
    release();

    // 4. Записи появились, N1 ≥ 20
    const rows = page.getByRole('button', { name: /ניטור, / }).filter({ visible: true });
    await expect(rows.nth(19)).toBeVisible();
    const n1 = await rows.count();
    expect(n1).toBeGreaterThanOrEqual(20);

    // 5. Догрузка: снова удерживаем ответ, жмём «ניטורים קודמים»
    held = new Promise<void>((r) => (release = r));
    const before = calls;
    const more = page.getByRole('button', { name: 'ניטורים קודמים' }).filter({ visible: true });
    await more.scrollIntoViewIfNeeded();
    await more.click();
    await expect.poll(() => calls).toBeGreaterThan(before);

    // 6. Пока ответ удержан — индикатор у «ניטורים קודמים»; затем новые записи
    await expect(page.getByRole('progressbar').filter({ visible: true }).first()).toBeVisible();
    release();
    await expect.poll(() => rows.count()).toBeGreaterThan(n1);
    const n2 = await rows.count();
    expect(n2 - n1).toBeLessThanOrEqual(20);
  });
});
